"use client";

import { useRender } from "@base-ui/react/use-render";
import type { Editor, Extensions } from "@tiptap/core";
import { EditorContent, useEditor } from "@tiptap/react";
import { createContext, useContext, useEffect, useMemo, useRef, useState } from "react";
import { useMarkdownEditor } from "./markdown-editor/context";
import { MarkdownEditorDragHandle } from "./markdown-editor/drag/drag-handle";
import { createRichEngine, pasteMarkdown } from "./markdown-editor/rich/engine";
import { createMarkdownCodec, markdownExtensions, requiresMarkdownSource } from "./markdown-editor/rich/extensions";
import { type MarkdownEditorContentProps, MarkdownEditorRoot, type MarkdownEditorRootProps } from "./markdown-editor/root";
import { MarkdownEditorSourceView } from "./markdown-editor/source-view";
import { MarkdownEditorTableControls } from "./markdown-editor/table/table-controls";
import { persistentUrlPolicy } from "./markdown-editor/url-policy";

export type { MarkdownEditorContentProps, MarkdownEditorStatus } from "./markdown-editor/root";

export type MarkdownEditorProps = MarkdownEditorRootProps & {
  /** Extra TipTap extensions, applied after the built-in Markdown set. Read once, when the editor mounts. */
  extensions?: Extensions;
};

type ContentAttributes = Record<string, string>;
const RichEditorContext = createContext<{ editor: Editor | null; setContentAttributes: (attributes: ContentAttributes) => void } | null>(
  null,
);

function useRichEditor() {
  const context = useContext(RichEditorContext);
  if (!context) throw new Error("MarkdownEditorContent requires a MarkdownEditor parent from the same module.");
  return context;
}

export function MarkdownEditor({
  extensions: extraExtensions,
  isUrlAllowed: urlPolicy = persistentUrlPolicy,
  ...props
}: MarkdownEditorProps) {
  const [isUrlAllowed] = useState(() => urlPolicy);
  const [options] = useState(() => ({ extensions: extraExtensions, isUrlAllowed }));
  const [codec] = useState(() => createMarkdownCodec(options));
  const [extensions] = useState(() => markdownExtensions(options));
  const [initialMarkdown] = useState(() => props.value ?? props.defaultValue ?? "");
  const [initialContent] = useState(() => (requiresMarkdownSource(initialMarkdown, codec, isUrlAllowed) ? "" : initialMarkdown));
  const [contentAttributes, setContentAttributes] = useState<ContentAttributes>({ role: "textbox", "aria-multiline": "true" });
  const editor = useEditor({
    extensions,
    immediatelyRender: false,
    shouldRerenderOnTransaction: false,
    content: initialContent,
    contentType: "markdown",
    editable: !props.disabled && !props.readOnly,
    editorProps: { attributes: contentAttributes, handlePaste: pasteMarkdown(codec, isUrlAllowed) },
  });
  const engine = useMemo(
    () => (editor ? createRichEngine(editor, codec, isUrlAllowed, initialMarkdown) : null),
    [editor, codec, isUrlAllowed, initialMarkdown],
  );
  return (
    <RichEditorContext value={{ editor, setContentAttributes }}>
      <MarkdownEditorRoot engine={engine} isUrlAllowed={isUrlAllowed} {...props} />
    </RichEditorContext>
  );
}

export function MarkdownEditorContent({ label, placeholder, autoFocus = false, ref, ...props }: MarkdownEditorContentProps) {
  const container = useRef<HTMLDivElement>(null);
  const { editor, setContentAttributes } = useRichEditor();
  const { disabled, readOnly, source } = useMarkdownEditor();
  const content = useRender({
    ref: [container, ref ?? null],
    render: (
      <div data-control-ui="markdown-editor" data-control-family="markdown-editor" data-slot="content" {...props}>
        <EditorContent editor={editor} />
        <MarkdownEditorDragHandle container={container} />
        <MarkdownEditorTableControls container={container} />
      </div>
    ),
  });
  useEffect(() => {
    setContentAttributes({
      role: "textbox",
      "aria-multiline": "true",
      "aria-label": label,
      "aria-disabled": String(disabled),
      "aria-readonly": String(readOnly),
      "data-placeholder": placeholder ?? "",
    });
  }, [setContentAttributes, label, disabled, readOnly, placeholder]);

  useEffect(() => {
    if (editor && !editor.isDestroyed && autoFocus && !source && !disabled) editor.commands.focus("end");
  }, [editor, autoFocus, source, disabled]);

  if (source || !editor)
    return <MarkdownEditorSourceView ref={ref} label={label} placeholder={placeholder} autoFocus={autoFocus} {...props} />;
  return content;
}

import type { Editor } from "@tiptap/core";
import { closeHistory } from "@tiptap/pm/history";
import type { Node as ProseMirrorNode, ResolvedPos, Slice } from "@tiptap/pm/model";
import { NodeSelection } from "@tiptap/pm/state";
import { createDragPreview, type DragPreview } from "../drag/drag-preview";
import type { MarkdownBlocks } from "../engine";

/** A list is not one block to its reader: the deepest list item is the unit you grab, anything else is its top-level block. */
function draggableBlockStart($pos: ResolvedPos): number {
  for (let depth = $pos.depth; depth > 1; depth--) {
    if ($pos.node(depth - 1).type.isInGroup("list")) return $pos.before(depth);
  }
  return $pos.depth > 0 ? $pos.before(1) : $pos.pos;
}

type PreparedDrag = {
  position: number;
  document: ProseMirrorNode;
  selection: NodeSelection;
  html: string;
  text: string;
  slice: Slice;
  source: HTMLElement | null;
  preview: DragPreview | null;
};

function prepare(editor: Editor, position: number): PreparedDrag | null {
  const { view, state } = editor;
  if (!state.doc.nodeAt(position)) return null;
  const selection = NodeSelection.create(state.doc, position);
  const node = view.nodeDOM(position);
  const source = node instanceof HTMLElement ? node : null;
  const { dom, text, slice } = view.serializeForClipboard(selection.content());
  return {
    position,
    document: state.doc,
    selection,
    html: dom.innerHTML,
    text,
    slice,
    source,
    preview: source ? createDragPreview([source], "tiptap") : null,
  };
}

export function createRichBlocks(editor: Editor): MarkdownBlocks {
  let prepared: PreparedDrag | null = null;
  const blockElement = (block: number) => {
    const node = editor.view.nodeDOM(block);
    return node instanceof HTMLElement ? node : null;
  };
  return {
    at(point) {
      const hit = editor.view.posAtCoords({ left: point.x, top: point.y });
      return hit ? draggableBlockStart(editor.state.doc.resolve(hit.pos)) : null;
    },
    atSelection: () => draggableBlockStart(editor.state.selection.$from),
    rect: (block) => blockElement(block)?.getBoundingClientRect() ?? null,
    select: (block) => {
      editor.commands.setNodeSelection(block);
    },
    move(block, direction) {
      const { doc, tr } = editor.state;
      const node = doc.nodeAt(block);
      const adjacent = node && (direction === -1 ? doc.resolve(block).nodeBefore : doc.nodeAt(block + node.nodeSize));
      if (!(node && adjacent)) return null;
      const target = direction === -1 ? block - adjacent.nodeSize : block + adjacent.nodeSize;
      tr.delete(block, block + node.nodeSize).insert(target, node);
      tr.setSelection(NodeSelection.create(tr.doc, target));
      editor.view.dispatch(closeHistory(tr).scrollIntoView());
      return target;
    },
    prepareDrag(block) {
      prepared = prepare(editor, block);
    },
    startDrag(block, transfer) {
      const payload = prepared?.position === block && prepared.document === editor.state.doc ? prepared : prepare(editor, block);
      prepared = null;
      if (!payload) return null;
      const { view } = editor;
      view.dispatch(view.state.tr.setSelection(payload.selection));
      transfer.clearData();
      transfer.setData("text/html", payload.html);
      transfer.setData("text/plain", payload.text);
      transfer.effectAllowed = "copyMove";
      view.dragging = { slice: payload.slice, move: true };
      return { preview: payload.preview, origin: payload.source?.getBoundingClientRect() ?? new DOMRect() };
    },
    endDrag() {
      prepared = null;
      if (!editor.isDestroyed) editor.view.dragging = null;
    },
  };
}

import { type ChainedCommands, type Editor, posToDOMRect } from "@tiptap/core";
import type { MarkdownManager } from "@tiptap/markdown";
import { Slice } from "@tiptap/pm/model";
import { EditorState, NodeSelection } from "@tiptap/pm/state";
import type { EditorView } from "@tiptap/pm/view";
import {
  type MarkdownBlockCommand,
  type MarkdownBlockType,
  type MarkdownEditorEngine,
  type MarkdownEditorSnapshot,
  type MarkdownMark,
  markdownHeadingLevels,
} from "../engine";
import type { MarkdownUrlPolicy } from "../url-policy";
import { createRichBlocks } from "./blocks";
import { hasMarkdownContent, requiresMarkdownSource } from "./extensions";
import { createRichTables } from "./tables";
import { createRichUploads } from "./uploads";

type Command = (chain: ChainedCommands) => ChainedCommands;

const markCommands: Record<MarkdownMark, Command> = {
  bold: (chain) => chain.toggleBold(),
  italic: (chain) => chain.toggleItalic(),
  strike: (chain) => chain.toggleStrike(),
  code: (chain) => chain.toggleCode(),
};

const blockCommands: Record<MarkdownBlockType, Command> = {
  bulletList: (chain) => chain.toggleBulletList(),
  orderedList: (chain) => chain.toggleOrderedList(),
  taskList: (chain) => chain.toggleTaskList(),
  blockquote: (chain) => chain.toggleBlockquote(),
  codeBlock: (chain) => chain.toggleCodeBlock(),
};

function replacementCommand(block: MarkdownBlockCommand): Command {
  switch (block.type) {
    case "paragraph":
      return (chain) => chain.clearNodes().setParagraph();
    case "heading":
      return (chain) => chain.clearNodes().setHeading({ level: block.level });
    case "horizontalRule":
      return (chain) => chain.setHorizontalRule();
    case "table":
      return (chain) => chain.insertTable({ rows: 3, cols: 3, withHeaderRow: true });
    default:
      return (chain) => blockCommands[block.type](chain.clearNodes());
  }
}

function rectAt(view: EditorView, position: number) {
  const coords = view.coordsAtPos(position);
  return new DOMRect(coords.left, coords.top, 1, coords.bottom - coords.top);
}

/** Plain-text Markdown pastes as formatted content, unless it holds Markdown this editor would lose. */
export function pasteMarkdown(codec: MarkdownManager, isUrlAllowed: MarkdownUrlPolicy) {
  return (view: EditorView, event: ClipboardEvent) => {
    const text = event.clipboardData?.getData("text/plain");
    if (!view.editable || !text || event.clipboardData?.getData("text/html") || requiresMarkdownSource(text, codec, isUrlAllowed))
      return false;
    const document = view.state.schema.nodeFromJSON(codec.parse(text));
    event.preventDefault();
    view.dispatch(view.state.tr.replaceSelection(Slice.maxOpen(document.content)).scrollIntoView());
    return true;
  };
}

export function createRichEngine(
  editor: Editor,
  codec: MarkdownManager,
  isUrlAllowed: MarkdownUrlPolicy,
  initialMarkdown: string,
): MarkdownEditorEngine {
  const listeners = new Set<() => void>();
  let markdown = initialMarkdown;
  let sourceRequired = requiresMarkdownSource(markdown, codec, isUrlAllowed);
  let emptiness = { document: editor.state.doc, isEmpty: !hasMarkdownContent(editor.state.doc) };
  let cache: { state: EditorState; editable: boolean; sourceRequired: boolean; snapshot: MarkdownEditorSnapshot } | null = null;
  const notify = () => {
    for (const listener of listeners) listener();
  };
  const run = (command: Command) => {
    command(editor.chain().focus()).run();
  };

  /** The empty paragraph kept after a closing block is a place to type, not content, so it never reaches the Markdown. */
  function serializeContent() {
    const content = editor.getJSON().content ?? [];
    const last = content.at(-1);
    const placeholder = content.length > 1 && last?.type === "paragraph" && !last.content?.length;
    return codec.serialize({ type: "doc", content: placeholder ? content.slice(0, -1) : content });
  }

  function isEmpty() {
    if (sourceRequired) return markdown.trim() === "";
    if (emptiness.document !== editor.state.doc) emptiness = { document: editor.state.doc, isEmpty: !hasMarkdownContent(editor.state.doc) };
    return emptiness.isEmpty;
  }

  function readSnapshot(): MarkdownEditorSnapshot {
    const { selection, doc } = editor.state;
    const headingLevel = editor.getAttributes("heading").level;
    const href = editor.getAttributes("link").href;
    const link = typeof href === "string" ? href : "";
    return {
      marks: {
        bold: editor.isActive("bold"),
        italic: editor.isActive("italic"),
        strike: editor.isActive("strike"),
        code: editor.isActive("code"),
      },
      blocks: {
        bulletList: editor.isActive("bulletList"),
        orderedList: editor.isActive("orderedList"),
        taskList: editor.isActive("taskList"),
        blockquote: editor.isActive("blockquote"),
        codeBlock: editor.isActive("codeBlock"),
      },
      heading: editor.isActive("heading") ? (markdownHeadingLevels.find((level) => level === headingLevel) ?? null) : null,
      link: editor.isActive("link") ? link : null,
      canUndo: editor.can().undo(),
      canRedo: editor.can().redo(),
      focused: editor.isFocused,
      formattable:
        !(selection instanceof NodeSelection) &&
        !selection.empty &&
        doc.textBetween(selection.from, selection.to).trim() !== "" &&
        !editor.isActive("codeBlock"),
      inlineOnly: editor.isActive("tableCell") || editor.isActive("tableHeader"),
      isEmpty: isEmpty(),
      sourceRequired,
    };
  }

  return {
    element: editor.view.dom,
    sourceView: "textarea",
    subscribe(listener) {
      listeners.add(listener);
      editor.on("transaction", listener);
      return () => {
        listeners.delete(listener);
        editor.off("transaction", listener);
      };
    },
    getSnapshot() {
      const { state, isEditable: editable } = editor;
      if (cache?.state === state && cache.editable === editable && cache.sourceRequired === sourceRequired) return cache.snapshot;
      cache = { state, editable, sourceRequired, snapshot: readSnapshot() };
      return cache.snapshot;
    },
    onChange(listener) {
      const handleUpdate = () => {
        const next = serializeContent();
        if (next === markdown) return;
        markdown = next;
        sourceRequired = requiresMarkdownSource(markdown, codec, isUrlAllowed);
        listener(markdown);
      };
      editor.on("update", handleUpdate);
      return () => {
        editor.off("update", handleUpdate);
      };
    },
    getMarkdown: () => markdown,
    setMarkdown(next) {
      if (next === markdown || editor.isDestroyed) return;
      markdown = next;
      sourceRequired = requiresMarkdownSource(next, codec, isUrlAllowed);
      if (sourceRequired) return notify();
      editor.commands.setContent(next, { contentType: "markdown", emitUpdate: false });
      editor.view.updateState(EditorState.create({ schema: editor.schema, doc: editor.state.doc, plugins: editor.state.plugins }));
      editor.view.dispatch(editor.state.tr);
    },
    setEditable(editable) {
      if (editor.isDestroyed || editor.isEditable === editable) return;
      editor.setEditable(editable, false);
      notify();
    },
    focus: () => {
      editor.commands.focus();
    },
    undo: () => run((chain) => chain.undo()),
    redo: () => run((chain) => chain.redo()),
    toggleMark: (mark) => run(markCommands[mark]),
    toggleBlock: (block) => run(blockCommands[block]),
    setHeading: (level) => run((chain) => (level ? chain.setHeading({ level }) : chain.setParagraph())),
    setLink: (target) =>
      run((chain) => (target ? chain.extendMarkRange("link").setLink({ href: target }) : chain.extendMarkRange("link").unsetLink())),
    insertImage: (image) => run((chain) => chain.setImage(image)),
    selectionRect() {
      const { from, to } = editor.state.selection;
      return editor.isDestroyed ? null : posToDOMRect(editor.view, from, to);
    },
    textBeforeCaret() {
      const { selection } = editor.state;
      const { $from } = selection;
      if (
        !editor.isFocused ||
        !selection.empty ||
        !$from.parent.isTextblock ||
        $from.parent.type.spec.code ||
        editor.isActive("code") ||
        editor.isActive("link")
      )
        return null;
      return { text: $from.parent.textBetween(0, $from.parentOffset, undefined, "\ufffc"), from: $from.start(), to: $from.pos };
    },
    caretRect: () => (editor.isDestroyed ? null : rectAt(editor.view, editor.state.selection.from)),
    replaceWithBlock: (range, block) => run((chain) => replacementCommand(block)(chain.deleteRange(range))),
    replaceWithMention: (range, mention) =>
      run((chain) =>
        chain.insertContentAt(range, [
          { type: "text", text: `@${mention.label}`, marks: [{ type: "link", attrs: { href: mention.href } }] },
          { type: "text", text: " " },
        ]),
      ),
    positionAt: (point) => editor.view.posAtCoords({ left: point.x, top: point.y })?.pos ?? null,
    uploads: createRichUploads(editor),
    blocks: createRichBlocks(editor),
    tables: createRichTables(editor),
  };
}

import { Extension, type Extensions, Node } from "@tiptap/core";
import Image from "@tiptap/extension-image";
import { TaskList } from "@tiptap/extension-list";
import Paragraph from "@tiptap/extension-paragraph";
import { TableKit } from "@tiptap/extension-table";
import { Markdown, MarkdownManager } from "@tiptap/markdown";
import type { Node as ProseMirrorNode } from "@tiptap/pm/model";
import StarterKit from "@tiptap/starter-kit";
import { markdownHeadingAttributes } from "@/components/control-ui/ui/markdown-heading";
import { type MarkdownUrlPolicy, persistentUrlPolicy } from "../url-policy";
import { MarkdownTaskItem } from "./task-item";

const MarkdownHeadings = Extension.create({
  name: "markdownHeadings",
  addGlobalAttributes() {
    return [
      {
        types: ["heading"],
        attributes: {
          markdownHeading: {
            default: null,
            renderHTML: (attributes) =>
              markdownHeadingAttributes(([1, 2, 3, 4, 5, 6] as const).find((level) => level === attributes.level) ?? 1),
          },
        },
      },
    ];
  },
});

export type MarkdownExtensionOptions = {
  /** Extra TipTap extensions, applied after the built-in Markdown set. */
  extensions?: Extensions;
  isUrlAllowed?: MarkdownUrlPolicy;
};

function safeImage(isUrlAllowed: MarkdownUrlPolicy) {
  return Image.extend({
    renderMarkdown: (node) => {
      const src = String(node.attrs?.src ?? "").replace(/[()]/g, (character) => `\\${character}`);
      const alt = String(node.attrs?.alt ?? "").replace(/[\\[\]]/g, (character) => `\\${character}`);
      const title = String(node.attrs?.title ?? "").replace(/[\\"]/g, (character) => `\\${character}`);
      return title ? `![${alt}](${src} "${title}")` : `![${alt}](${src})`;
    },
    // a pasted image with a refused URL would save as "![alt]()" and force the whole document into source mode
    parseHTML() {
      return [
        {
          tag: 'img[src]:not([src^="data:"])',
          getAttrs: (element) => (isUrlAllowed(element.getAttribute("src") ?? "", "image") ? null : false),
        },
      ];
    },
    addAttributes() {
      return {
        ...this.parent?.(),
        src: {
          default: null,
          parseHTML: (element) => {
            const src = element.getAttribute("src") ?? "";
            return isUrlAllowed(src, "image") ? src : null;
          },
          renderHTML: (attributes) => ({ src: isUrlAllowed(attributes.src ?? "", "image") ? attributes.src : undefined }),
        },
      };
    },
  });
}

const MarkdownParagraph = Paragraph.extend({
  parseMarkdown: (token, helpers) => {
    const content = helpers.parseInline(token.tokens ?? []);
    const first = content[0];
    const empty = content.length === 1 && first?.type === "text" && ["&nbsp;", "\u00a0"].includes(first.text ?? "");
    return helpers.createNode("paragraph", undefined, empty ? [] : content);
  },
});

export const ImageUpload = Node.create({
  name: "imageUpload",
  group: "block",
  atom: true,
  selectable: true,
  addAttributes: () => ({ id: { default: null }, name: { default: "Image" } }),
  renderHTML: ({ node }) => ["div", { "data-image-upload": "", role: "status" }, `Image: ${node.attrs.name}`],
  renderMarkdown: () => "",
});

export function markdownExtensions({ extensions = [], isUrlAllowed = persistentUrlPolicy }: MarkdownExtensionOptions = {}) {
  return [
    StarterKit.configure({
      underline: false,
      paragraph: false,
      dropcursor: { color: false, width: 2 },
      link: { openOnClick: false, isAllowedUri: (url) => isUrlAllowed(url, "link") },
    }),
    MarkdownParagraph,
    MarkdownHeadings,
    safeImage(isUrlAllowed).configure({ allowBase64: false, inline: true }),
    TaskList,
    MarkdownTaskItem.configure({ nested: true, HTMLAttributes: { "data-type": "taskItem" } }),
    TableKit.configure({ table: { resizable: false } }),
    ImageUpload,
    Markdown,
    ...extensions,
  ];
}

export function createMarkdownCodec(options?: MarkdownExtensionOptions) {
  return new MarkdownManager({ extensions: markdownExtensions(options) });
}

const supportedTokens = new Set([
  "space",
  "code",
  "heading",
  "hr",
  "blockquote",
  "list",
  "list_item",
  "paragraph",
  "text",
  "escape",
  "link",
  "image",
  "strong",
  "em",
  "codespan",
  "br",
  "del",
  "table",
  "def",
  "taskList",
  "taskItem",
]);

function unsupportedToken(value: unknown, isUrlAllowed: MarkdownUrlPolicy): boolean {
  if (Array.isArray(value)) return value.some((item) => unsupportedToken(item, isUrlAllowed));
  if (typeof value !== "object" || value === null) return false;
  if ("type" in value && typeof value.type === "string") {
    if (!supportedTokens.has(value.type)) return true;
    if (
      (value.type === "image" || value.type === "link") &&
      "href" in value &&
      typeof value.href === "string" &&
      !isUrlAllowed(value.href, value.type)
    )
      return true;
  }
  return Object.values(value).some((item) => unsupportedToken(item, isUrlAllowed));
}

export function requiresMarkdownSource(
  markdown: string,
  codec: MarkdownManager,
  isUrlAllowed: MarkdownUrlPolicy = persistentUrlPolicy,
): boolean {
  return unsupportedToken(codec.instance.lexer(markdown), isUrlAllowed);
}

/** Pending uploads, empty task items and blank paragraphs are not content; text and images are. */
export function hasMarkdownContent(document: ProseMirrorNode): boolean {
  let found = false;
  document.descendants((node) => {
    found ||= node.type.name === "image" || Boolean(node.isText && node.text?.trim());
    return !found;
  });
  return found;
}

import type { ChainedCommands, Editor } from "@tiptap/core";
import type { ResolvedPos } from "@tiptap/pm/model";
import { CellSelection, cellAround, moveTableColumn, moveTableRow, TableMap } from "@tiptap/pm/tables";
import type { MarkdownTableAxis, MarkdownTables } from "../engine";
import { canMoveLine, tableSize } from "../table/table-geometry";

type RichCell = { tablePos: number; row: number; column: number };

function cellFrom($pos: ResolvedPos): RichCell | null {
  const $cell = cellAround($pos);
  if (!$cell) return null;
  const tableStart = $cell.start(-1);
  const { left, top } = TableMap.get($cell.node(-1)).findCell($cell.pos - tableStart);
  return { tablePos: tableStart - 1, row: top, column: left };
}

/** Tables render as `div.tableWrapper > table`, so the element is the node view's first child. */
function tableElementAt(editor: Editor, tablePos: number) {
  const wrapper = editor.view.nodeDOM(tablePos);
  if (wrapper instanceof HTMLTableElement) return wrapper;
  const table = wrapper instanceof HTMLElement ? wrapper.firstElementChild : null;
  return table instanceof HTMLTableElement ? table : null;
}

function tablePosOf(editor: Editor, table: HTMLTableElement) {
  const cell = table.rows[0]?.cells[0];
  if (!(cell && editor.view.dom.contains(cell))) return null;
  return cellFrom(editor.state.doc.resolve(editor.view.posAtDOM(cell, 0)))?.tablePos ?? null;
}

function cellStart(editor: Editor, tablePos: number, row: number, column: number) {
  const table = editor.state.doc.nodeAt(tablePos);
  if (table?.type.spec.tableRole !== "table") return null;
  return tablePos + 1 + TableMap.get(table).positionAt(row, column, table);
}

export function createRichTables(editor: Editor): MarkdownTables {
  function lineStart(tablePos: number, axis: MarkdownTableAxis, index: number) {
    return axis === "row" ? cellStart(editor, tablePos, index, 0) : cellStart(editor, tablePos, 0, index);
  }
  function inLine(table: HTMLTableElement, axis: MarkdownTableAxis, index: number, apply: (chain: ChainedCommands) => ChainedCommands) {
    const tablePos = tablePosOf(editor, table);
    const position = tablePos === null ? null : lineStart(tablePos, axis, index);
    if (position !== null)
      apply(
        editor
          .chain()
          .focus()
          .setTextSelection(position + 2),
      ).run();
  }
  function inLastCell(table: HTMLTableElement, row: number, apply: (chain: ChainedCommands) => ChainedCommands) {
    const tablePos = tablePosOf(editor, table);
    const position = tablePos === null ? null : cellStart(editor, tablePos, row, tableSize(table).columns - 1);
    if (position !== null)
      apply(
        editor
          .chain()
          .focus()
          .setTextSelection(position + 2),
      ).run();
  }
  return {
    caret() {
      const cell = cellFrom(editor.state.selection.$from);
      const table = cell && tableElementAt(editor, cell.tablePos);
      return cell && table ? { table, row: cell.row, column: cell.column } : null;
    },
    select(table, axis, index) {
      const tablePos = tablePosOf(editor, table);
      const position = tablePos === null ? null : lineStart(tablePos, axis, index);
      if (position === null) return;
      const $cell = editor.state.doc.resolve(position);
      editor.view.dispatch(
        editor.state.tr.setSelection(axis === "row" ? CellSelection.rowSelection($cell) : CellSelection.colSelection($cell)),
      );
    },
    move(table, axis, from, to) {
      const tablePos = tablePosOf(editor, table);
      const inside = tablePos === null ? null : cellStart(editor, tablePos, 0, 0);
      const size = tableSize(table);
      if (inside === null || !canMoveLine(axis === "row" ? size.rows : size.columns, axis, from, to)) return false;
      const command = axis === "row" ? moveTableRow : moveTableColumn;
      return command({ from, to, pos: inside + 1, select: true })(editor.state, editor.view.dispatch);
    },
    insert(table, axis, index, side) {
      inLine(table, axis, index, (chain) => {
        if (axis === "row") return side === "before" ? chain.addRowBefore() : chain.addRowAfter();
        return side === "before" ? chain.addColumnBefore() : chain.addColumnAfter();
      });
    },
    remove(table, axis, index) {
      inLine(table, axis, index, (chain) => (axis === "row" ? chain.deleteRow() : chain.deleteColumn()));
    },
    align(table, column, align) {
      const tablePos = tablePosOf(editor, table);
      const position = tablePos === null ? null : cellStart(editor, tablePos, 0, column);
      if (position === null) return;
      editor
        .chain()
        .focus()
        .command(({ tr }) => {
          tr.setSelection(CellSelection.colSelection(tr.doc.resolve(position)));
          return true;
        })
        .setCellAttribute("align", align)
        .run();
    },
    append(table, axis) {
      if (axis === "row") inLastCell(table, tableSize(table).rows - 1, (chain) => chain.addRowAfter().goToNextCell());
      else inLastCell(table, 0, (chain) => chain.addColumnAfter().goToNextCell());
    },
  };
}

